function search(a, x) {
  let lo = 0;
  let hi = a.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (a[mid] === x) return mid;
    a[mid] < x ? (lo = mid + 1) : (hi = mid);
  }
  return -1;
}

